## Port Position Calculation

To draw a cable from outlet A to inlet B:

```javascript
function getPortCenter(portEl, canvasEl) {
  const portRect = portEl.getBoundingClientRect();
  const canvasRect = canvasEl.getBoundingClientRect();
  return {
    x: portRect.left + portRect.width / 2 - canvasRect.left,
    y: portRect.top + portRect.height / 2 - canvasRect.top,
  };
}

function drawCable(edgeId, outletEl, inletEl, canvasEl, svgEl) {
  const src = getPortCenter(outletEl, canvasEl);
  const dst = getPortCenter(inletEl, canvasEl);

  let path = svgEl.querySelector(`[data-edge="${edgeId}"]`);
  if (!path) {
    path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.dataset.edge = edgeId;
    path.setAttribute('class', 'pn-cable');
    path.setAttribute('stroke', 'var(--pn-cable)');
    path.setAttribute('stroke-width', '2');
    path.setAttribute('fill', 'none');
    svgEl.appendChild(path);
  }
  path.setAttribute('d', `M ${src.x} ${src.y} L ${dst.x} ${dst.y}`);
}
```

**Note:** Cable positions must be recalculated when objects move (on drag). This is done by re-reading DOM positions and updating the SVG `d` attribute.

